// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker attacker;

    function setUp() public { c = new ReentrancyDAO(); attacker = new Attacker(); }

    // fuzzed params: attackerKey (private key used to get an address) and amount
    function testFuzz_property(uint256 attackerKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        attackerKey = bound(attackerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amount in a reasonable range and non-zero
        amount = bound(amount, 1, 1 ether);

        // derive an address for the attacker EOA and fund it
        address atkEOA = vm.addr(uint256(attackerKey));
        vm.deal(atkEOA, 2 ether);

        // fund the attacker contract so it can receive callbacks with value
        vm.deal(address(attacker), 2 ether);

        // The attacker contract will act as msg.sender when re-entering: set its target c
        attacker.setTarget(address(c));

        // make the EOA deposit into C as the attacker contract's address so that
        // when c.withdrawAll sends value it goes to the attacker contract (which re-enters)
        // We use vm.prank to have the attacker contract perform deposit (must be an EOA or contract)
        // First, from the EOA, instruct the contract to forward the deposit: have the EOA call
        // the attacker which will call c.deposit{value: amount}()
        vm.prank(atkEOA);
        attacker.doDeposit{value: amount}(address(c));

        // Now the attacker contract has credit in c. We will call withdrawAll from the attacker contract
        // so that when c makes the external call it calls back into attacker (reentrancy).
        // The reentrant call in Attacker will try to call withdrawAll again.
        // Execute withdrawAll() via the attacker contract (so msg.sender in C is attacker contract)
        // Ensure attacker contract has enough ETH to receive the payout.
        vm.prank(address(attacker));
        attacker.triggerWithdraw(address(c));

        // After withdrawAll completes, the correct C should have zero credit for attacker
        // Observe via the public getter: credit is private in original; but we can detect by attempting
        // to withdraw again: in the reference, second withdrawAll will do nothing (no further transfer)
        // We detect that by observing address(c).balance change when calling withdrawAll a second time.

        // Record contract balance before second withdraw
        uint256 before = address(c).balance;

        // Try second withdraw: run it from attacker and record if it transfers any ETH out
        // We call via try/catch to avoid bubbling reverts
        vm.prank(address(attacker));
        try c.withdrawAll() {
            // success
        } catch {}

        uint256 after_ = address(c).balance;

        // If the reference holds, second withdraw sends nothing and balance is unchanged: before == after
        // The mutant (vulnerable to reentrancy) can leave credit > 0 so a second withdraw would transfer funds
        // causing after < before. We assert that for ALL inputs (attackerKey, amount) the reference keeps
        // before == after. This will fail on the mutant for some inputs that the fuzzer will find.
        assertTrue(before == after_);
    }
}

// Minimal attacker contract that records and re-enters exactly once during receive()
contract Attacker {
    address public target;
    bool private entered;

    function setTarget(address _t) external { target = _t; }

    // helper to perform a deposit into C from this contract
    function doDeposit(address cAddr) external payable {
        // forward the ETH sent by the EOA into C.deposit
        ReentrancyDAO(cAddr).deposit{value: msg.value}();
    }

    // trigger withdraw from this contract (so msg.sender in C is this contract)
    function triggerWithdraw(address cAddr) external {
        ReentrancyDAO(cAddr).withdrawAll();
    }

    // receive will re-enter C.withdrawAll exactly once to attempt reentrancy
    receive() external payable {
        if (!entered) {
            entered = true;
            // re-enter withdrawAll on the target contract
            ReentrancyDAO(target).withdrawAll();
        }
    }
}
